% mathsmap-diagram-colours {"version":1,"kind":"geometry","base":[],"semantic":[{"name":"shiftBlue","hex":"268CFF","reason":"decimal shifts and corresponding exponents"},{"name":"displacedGrey","hex":"777777","reason":"zeros displaced by moving the decimal point"}],"reference":"source page 18 p18-decimal-shifts"}
\begingroup
\fontsize{10}{12}\selectfont
\begin{tikzpicture}[x=1mm,y=1mm,every node/.style={anchor=base west,inner sep=0pt,outer sep=0pt,font=\fontsize{10}{12}\selectfont}]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{shiftBlue}{HTML}{268CFF}
\definecolor{displacedGrey}{HTML}{777777}
\path[use as bounding box] (0,-44) rectangle (155,4);
\node at (0,0) {$3000000.$};
\node (leftone) at (0,-10) {$300000.\textcolor{displacedGrey}{0}\times10^{\textcolor{shiftBlue}{1}}$};
\node (lefttwo) at (0,-20) {$30000.\textcolor{displacedGrey}{00}\times10^{\textcolor{shiftBlue}{2}}$};
\node (leftthree) at (0,-30) {$3000.\textcolor{displacedGrey}{000}\times10^{\textcolor{shiftBlue}{3}}$};
\node (leftfour) at (0,-40) {$300.\textcolor{displacedGrey}{0000}\times10^{\textcolor{shiftBlue}{4}}$};
\pgfmathsetlengthmacro{\digitWidth}{width("$0$")}
\pgfmathsetlengthmacro{\halfDot}{0.5*width("$.$")}
\foreach \row/\prefix/\count in {leftone/300000/1,lefttwo/30000/2,leftthree/3000/3,leftfour/300/4}{
\pgfmathsetlengthmacro{\startOffset}{width("$\prefix$")+\halfDot}
\coordinate (previous) at ([xshift=\startOffset,yshift=-0.6mm]\row.base west);
\foreach \step in {1,...,\count}{
\pgfmathsetlengthmacro{\nextOffset}{width("$\prefix.$")+\step*\digitWidth}
\coordinate (next) at ([xshift=\nextOffset,yshift=-0.6mm]\row.base west);
\draw[shiftBlue,line width=0.4pt] (previous) .. controls +(0,-1.5mm) and +(0,-1.5mm) .. (next);
\coordinate (previous) at (next);
}}
\node at (82,0) {$\textcolor{displacedGrey}{0}.000032$};
\node (rightone) at (82,-10) {$\textcolor{displacedGrey}{00}.00032\times10^{\textcolor{shiftBlue}{-1}}$};
\node (righttwo) at (82,-20) {$\textcolor{displacedGrey}{000}.0032\times10^{\textcolor{shiftBlue}{-2}}$};
\node (rightthree) at (82,-30) {$\textcolor{displacedGrey}{0000}.032\times10^{\textcolor{shiftBlue}{-3}}$};
\node (rightfour) at (82,-40) {$\textcolor{displacedGrey}{00000}.32\times10^{\textcolor{shiftBlue}{-4}}$};
\foreach \row/\count in {rightone/1,righttwo/2,rightthree/3,rightfour/4}{
\coordinate (previous) at ([xshift=\digitWidth,yshift=-0.6mm]\row.base west);
\foreach \step in {1,...,\count}{
\pgfmathsetlengthmacro{\nextOffset}{(\step+1)*\digitWidth}
\ifnum\step=\count\relax
\pgfmathsetlengthmacro{\nextOffset}{(\step+1)*\digitWidth+\halfDot}
\fi
\coordinate (next) at ([xshift=\nextOffset,yshift=-0.6mm]\row.base west);
\draw[shiftBlue,line width=0.4pt] (previous) .. controls +(0,-1.5mm) and +(0,-1.5mm) .. (next);
\coordinate (previous) at (next);
}}
\end{tikzpicture}
\endgroup

